/**
 * The image formats handed to the application.
 */
export enum LogoFormat {
  /**
   * PNG.
   */
  Png,
  /**
   * JPEG.
   */
  Jpeg,
  /**
   * WebP.
   */
  Webp,
  /**
   * SVG.
   */
  Svg,
}

const FfiConverterTypeLogoFormat = (() => {
  type TypeName = LogoFormat;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return LogoFormat.Png;
        case 2:
          return LogoFormat.Jpeg;
        case 3:
          return LogoFormat.Webp;
        case 4:
          return LogoFormat.Svg;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case LogoFormat.Png:
          return c.writeI32(1);
        case LogoFormat.Jpeg:
          return c.writeI32(2);
        case LogoFormat.Webp:
          return c.writeI32(3);
        case LogoFormat.Svg:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

